from collections import defaultdict
for n in (20,40,80,120):
 # compute A separately per start? E from all paths impossible; dynamic q from start0 gives E for a=-min only, does give all A values over increments indeed counts but floating
 d={(0,0,0):1}
 for _ in range(n):
  nd=defaultdict(int)
  for (lo,hi,z),c in d.items():
   for h in (-1,1):
    q=z+h;nd[(min(lo,q),max(hi,q),q)]+=c
  d=nd
 E=defaultdict(dict)
 for (lo,hi,z),c in d.items():E[(hi-lo,z-lo)][-lo]=c
 bad=0
 for (w,e),vals in E.items():
  seq=[vals.get(a,0) for a in range((n+e)&1,w+1,2)]
  # differences should go neg then pos (zeros ignored included)
  seenpos=False
  for x,y in zip(seq,seq[1:]):
   if y>x:seenpos=True
   elif y<x and seenpos:bad+=1;break
 print(n,'bad',bad,'states',len(d))
